from __future__ import annotations

import base64
import json
import os
import time
import uuid
from dataclasses import dataclass
from enum import Enum
from pathlib import Path
from typing import Any, Mapping, Protocol, runtime_checkable

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError


class DeploymentProfile(str, Enum):
    AWS = "aws"
    ONPREM = "onprem"


def resolve_profile(env: Mapping[str, str] | None = None) -> DeploymentProfile:
    source = env if env is not None else os.environ
    raw_value = source.get("DEPLOYMENT_PROFILE", DeploymentProfile.ONPREM.value).strip().lower()

    try:
        return DeploymentProfile(raw_value)
    except ValueError as exc:
        valid = ", ".join(profile.value for profile in DeploymentProfile)
        raise ValueError(f"Unsupported DEPLOYMENT_PROFILE={raw_value!r}. Expected one of: {valid}.") from exc


def _normalize_name(value: str) -> str:
    return "".join(character if character.isalnum() else "_" for character in value).upper()


def _json_or_passthrough(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    if isinstance(value, str):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return value
    return value


def _serialize_payload(value: Any) -> str:
    if isinstance(value, str):
        return value
    return json.dumps(value, sort_keys=True)


@runtime_checkable
class RuntimeAdapter(Protocol):
    profile: DeploymentProfile


@runtime_checkable
class ObjectStoragePort(RuntimeAdapter, Protocol):
    def put_object(self, key: str, data: bytes, *, content_type: str = "application/octet-stream") -> str:
        ...

    def get_object(self, key: str) -> bytes:
        ...


@runtime_checkable
class QueuePort(RuntimeAdapter, Protocol):
    def send_message(self, queue_name: str, payload: Any) -> str:
        ...

    def receive_messages(self, queue_name: str, *, max_messages: int = 1, wait_seconds: int = 0) -> list[Any]:
        ...


@runtime_checkable
class EventingPort(RuntimeAdapter, Protocol):
    def publish_event(
        self,
        source: str,
        detail_type: str,
        detail: Mapping[str, Any],
        *,
        bus_name: str | None = None,
    ) -> str:
        ...


@runtime_checkable
class SecretsPort(RuntimeAdapter, Protocol):
    def get_secret(self, name: str) -> str:
        ...


@runtime_checkable
class LogSinkPort(RuntimeAdapter, Protocol):
    def emit(self, level: str, message: str, *, context: Mapping[str, Any] | None = None) -> None:
        ...


PARITY_RULES: dict[str, tuple[str, ...]] = {
    "object_storage": ("put_object", "get_object"),
    "queue": ("send_message", "receive_messages"),
    "eventing": ("publish_event",),
    "secrets": ("get_secret",),
    "log_sink": ("emit",),
}


@dataclass(frozen=True)
class AdapterSettings:
    profile: DeploymentProfile
    region: str
    object_storage_bucket: str
    object_storage_endpoint_url: str | None
    queue_endpoint_url: str | None
    eventing_endpoint_url: str | None
    secrets_endpoint_url: str | None
    log_sink_endpoint_url: str | None
    aws_event_bus_name: str
    aws_log_group_name: str
    aws_log_stream_name: str
    onprem_queue_dir: Path
    onprem_event_log_path: Path
    onprem_log_path: Path
    onprem_secret_dir: Path | None
    secret_env_prefix: str
    aws_access_key_id: str | None
    aws_secret_access_key: str | None
    aws_session_token: str | None

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> "AdapterSettings":
        source = env if env is not None else os.environ
        secret_dir_value = source.get("ONPREM_SECRETS_DIR")

        return cls(
            profile=resolve_profile(source),
            region=source.get("AWS_REGION", "us-east-1"),
            object_storage_bucket=source.get("OBJECT_STORAGE_BUCKET", "req001-artifacts"),
            object_storage_endpoint_url=source.get("OBJECT_STORAGE_ENDPOINT_URL"),
            queue_endpoint_url=source.get("QUEUE_ENDPOINT_URL"),
            eventing_endpoint_url=source.get("EVENTING_ENDPOINT_URL"),
            secrets_endpoint_url=source.get("SECRETS_ENDPOINT_URL"),
            log_sink_endpoint_url=source.get("LOG_SINK_ENDPOINT_URL"),
            aws_event_bus_name=source.get("AWS_EVENT_BUS_NAME", "default"),
            aws_log_group_name=source.get("AWS_LOG_GROUP_NAME", "req001"),
            aws_log_stream_name=source.get("AWS_LOG_STREAM_NAME", "adapter-registry"),
            onprem_queue_dir=Path(source.get("ONPREM_QUEUE_DIR", ".runtime/queues")),
            onprem_event_log_path=Path(source.get("ONPREM_EVENT_LOG_PATH", ".runtime/events.jsonl")),
            onprem_log_path=Path(source.get("ONPREM_LOG_PATH", ".runtime/app.log.jsonl")),
            onprem_secret_dir=Path(secret_dir_value) if secret_dir_value else None,
            secret_env_prefix=source.get("SECRET_ENV_PREFIX", "SECRET_"),
            aws_access_key_id=source.get("AWS_ACCESS_KEY_ID"),
            aws_secret_access_key=source.get("AWS_SECRET_ACCESS_KEY"),
            aws_session_token=source.get("AWS_SESSION_TOKEN"),
        )


def _build_boto3_client(service_name: str, settings: AdapterSettings, endpoint_url: str | None) -> Any:
    client_kwargs: dict[str, Any] = {"region_name": settings.region}

    if settings.aws_access_key_id:
        client_kwargs["aws_access_key_id"] = settings.aws_access_key_id
    if settings.aws_secret_access_key:
        client_kwargs["aws_secret_access_key"] = settings.aws_secret_access_key
    if settings.aws_session_token:
        client_kwargs["aws_session_token"] = settings.aws_session_token
    if endpoint_url:
        client_kwargs["endpoint_url"] = endpoint_url
    if service_name == "s3":
        client_kwargs["config"] = Config(signature_version="s3v4", s3={"addressing_style": "path"})

    return boto3.client(service_name, **client_kwargs)


class _S3CompatibleObjectStorageAdapter:
    def __init__(self, profile: DeploymentProfile, settings: AdapterSettings) -> None:
        self.profile = profile
        self._settings = settings
        self._bucket = settings.object_storage_bucket
        self._client = _build_boto3_client("s3", settings, settings.object_storage_endpoint_url)

    def _ensure_bucket(self) -> None:
        try:
            self._client.head_bucket(Bucket=self._bucket)
            return
        except ClientError:
            pass

        create_kwargs: dict[str, Any] = {"Bucket": self._bucket}
        if self._settings.region != "us-east-1":
            create_kwargs["CreateBucketConfiguration"] = {"LocationConstraint": self._settings.region}
        self._client.create_bucket(**create_kwargs)

    def put_object(self, key: str, data: bytes, *, content_type: str = "application/octet-stream") -> str:
        self._ensure_bucket()
        self._client.put_object(Bucket=self._bucket, Key=key, Body=data, ContentType=content_type)
        return key

    def get_object(self, key: str) -> bytes:
        response = self._client.get_object(Bucket=self._bucket, Key=key)
        return response["Body"].read()


class AwsObjectStorageAdapter(_S3CompatibleObjectStorageAdapter):
    def __init__(self, settings: AdapterSettings) -> None:
        super().__init__(DeploymentProfile.AWS, settings)


class OnPremObjectStorageAdapter(_S3CompatibleObjectStorageAdapter):
    def __init__(self, settings: AdapterSettings) -> None:
        super().__init__(DeploymentProfile.ONPREM, settings)


class AwsQueueAdapter:
    profile = DeploymentProfile.AWS

    def __init__(self, settings: AdapterSettings) -> None:
        self._client = _build_boto3_client("sqs", settings, settings.queue_endpoint_url)

    def _queue_url(self, queue_name: str) -> str:
        try:
            return self._client.get_queue_url(QueueName=queue_name)["QueueUrl"]
        except ClientError as exc:
            error_code = exc.response.get("Error", {}).get("Code")
            if error_code not in {"AWS.SimpleQueueService.NonExistentQueue", "QueueDoesNotExist"}:
                raise
            return self._client.create_queue(QueueName=queue_name)["QueueUrl"]

    def send_message(self, queue_name: str, payload: Any) -> str:
        response = self._client.send_message(QueueUrl=self._queue_url(queue_name), MessageBody=_serialize_payload(payload))
        return response["MessageId"]

    def receive_messages(self, queue_name: str, *, max_messages: int = 1, wait_seconds: int = 0) -> list[Any]:
        response = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=max_messages,
            WaitTimeSeconds=wait_seconds,
        )
        messages = response.get("Messages", [])
        parsed_messages: list[Any] = []

        for message in messages:
            parsed_messages.append(_json_or_passthrough(message["Body"]))
            self._client.delete_message(QueueUrl=self._queue_url(queue_name), ReceiptHandle=message["ReceiptHandle"])

        return parsed_messages


class OnPremQueueAdapter:
    profile = DeploymentProfile.ONPREM

    def __init__(self, settings: AdapterSettings) -> None:
        self._base_path = settings.onprem_queue_dir

    def _queue_dir(self, queue_name: str) -> Path:
        directory = self._base_path / queue_name
        directory.mkdir(parents=True, exist_ok=True)
        return directory

    def send_message(self, queue_name: str, payload: Any) -> str:
        message_id = str(uuid.uuid4())
        message_path = self._queue_dir(queue_name) / f"{time.time_ns()}-{message_id}.json"
        message_path.write_text(
            json.dumps({"id": message_id, "payload": payload}, sort_keys=True),
            encoding="utf-8",
        )
        return message_id

    def receive_messages(self, queue_name: str, *, max_messages: int = 1, wait_seconds: int = 0) -> list[Any]:
        if wait_seconds:
            time.sleep(wait_seconds)

        queue_dir = self._queue_dir(queue_name)
        messages: list[Any] = []

        for message_path in sorted(queue_dir.glob("*.json"))[:max_messages]:
            payload = json.loads(message_path.read_text(encoding="utf-8"))["payload"]
            message_path.unlink()
            messages.append(payload)

        return messages


class AwsEventingAdapter:
    profile = DeploymentProfile.AWS

    def __init__(self, settings: AdapterSettings) -> None:
        self._client = _build_boto3_client("events", settings, settings.eventing_endpoint_url)
        self._default_bus_name = settings.aws_event_bus_name

    def publish_event(
        self,
        source: str,
        detail_type: str,
        detail: Mapping[str, Any],
        *,
        bus_name: str | None = None,
    ) -> str:
        response = self._client.put_events(
            Entries=[
                {
                    "Source": source,
                    "DetailType": detail_type,
                    "Detail": json.dumps(dict(detail), sort_keys=True),
                    "EventBusName": bus_name or self._default_bus_name,
                }
            ]
        )
        if response.get("FailedEntryCount", 0):
            raise RuntimeError(f"EventBridge rejected event: {response['Entries']}")
        return response["Entries"][0]["EventId"]


class OnPremEventingAdapter:
    profile = DeploymentProfile.ONPREM

    def __init__(self, settings: AdapterSettings) -> None:
        self._event_log_path = settings.onprem_event_log_path

    def publish_event(
        self,
        source: str,
        detail_type: str,
        detail: Mapping[str, Any],
        *,
        bus_name: str | None = None,
    ) -> str:
        event_id = str(uuid.uuid4())
        self._event_log_path.parent.mkdir(parents=True, exist_ok=True)
        with self._event_log_path.open("a", encoding="utf-8") as handle:
            handle.write(
                json.dumps(
                    {
                        "id": event_id,
                        "source": source,
                        "detail_type": detail_type,
                        "detail": dict(detail),
                        "bus_name": bus_name or "onprem-default",
                        "timestamp_ms": int(time.time() * 1000),
                    },
                    sort_keys=True,
                )
                + "\n"
            )
        return event_id


class AwsSecretsAdapter:
    profile = DeploymentProfile.AWS

    def __init__(self, settings: AdapterSettings) -> None:
        self._client = _build_boto3_client("secretsmanager", settings, settings.secrets_endpoint_url)

    def get_secret(self, name: str) -> str:
        response = self._client.get_secret_value(SecretId=name)
        if "SecretString" in response:
            return response["SecretString"]
        return base64.b64decode(response["SecretBinary"]).decode("utf-8")


class OnPremSecretsAdapter:
    profile = DeploymentProfile.ONPREM

    def __init__(self, settings: AdapterSettings) -> None:
        self._secret_dir = settings.onprem_secret_dir
        self._secret_env_prefix = settings.secret_env_prefix

    def get_secret(self, name: str) -> str:
        env_name = f"{self._secret_env_prefix}{_normalize_name(name)}"
        env_value = os.environ.get(env_name)
        if env_value is not None:
            return env_value

        if self._secret_dir:
            secret_path = self._secret_dir / name
            if secret_path.exists():
                return secret_path.read_text(encoding="utf-8").strip()

        raise KeyError(f"Secret {name!r} was not found in environment or ONPREM_SECRETS_DIR.")


class AwsLogSinkAdapter:
    profile = DeploymentProfile.AWS

    def __init__(self, settings: AdapterSettings) -> None:
        self._client = _build_boto3_client("logs", settings, settings.log_sink_endpoint_url)
        self._log_group_name = settings.aws_log_group_name
        self._log_stream_name = settings.aws_log_stream_name
        self._sequence_token: str | None = None

    def _ensure_stream(self) -> None:
        try:
            self._client.create_log_group(logGroupName=self._log_group_name)
        except ClientError as exc:
            if exc.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
                raise

        try:
            self._client.create_log_stream(
                logGroupName=self._log_group_name,
                logStreamName=self._log_stream_name,
            )
        except ClientError as exc:
            if exc.response.get("Error", {}).get("Code") != "ResourceAlreadyExistsException":
                raise

    def emit(self, level: str, message: str, *, context: Mapping[str, Any] | None = None) -> None:
        self._ensure_stream()
        payload = {
            "level": level,
            "message": message,
            "context": dict(context or {}),
            "timestamp_ms": int(time.time() * 1000),
        }
        request: dict[str, Any] = {
            "logGroupName": self._log_group_name,
            "logStreamName": self._log_stream_name,
            "logEvents": [{"timestamp": payload["timestamp_ms"], "message": json.dumps(payload, sort_keys=True)}],
        }
        if self._sequence_token:
            request["sequenceToken"] = self._sequence_token

        try:
            response = self._client.put_log_events(**request)
        except ClientError as exc:
            error_code = exc.response.get("Error", {}).get("Code")
            if error_code not in {"InvalidSequenceTokenException", "DataAlreadyAcceptedException"}:
                raise
            describe_response = self._client.describe_log_streams(
                logGroupName=self._log_group_name,
                logStreamNamePrefix=self._log_stream_name,
            )
            streams = describe_response.get("logStreams", [])
            token = streams[0].get("uploadSequenceToken") if streams else None
            if token:
                request["sequenceToken"] = token
            else:
                request.pop("sequenceToken", None)
            response = self._client.put_log_events(**request)

        self._sequence_token = response.get("nextSequenceToken")


class OnPremLogSinkAdapter:
    profile = DeploymentProfile.ONPREM

    def __init__(self, settings: AdapterSettings) -> None:
        self._log_path = settings.onprem_log_path

    def emit(self, level: str, message: str, *, context: Mapping[str, Any] | None = None) -> None:
        self._log_path.parent.mkdir(parents=True, exist_ok=True)
        with self._log_path.open("a", encoding="utf-8") as handle:
            handle.write(
                json.dumps(
                    {
                        "level": level,
                        "message": message,
                        "context": dict(context or {}),
                        "timestamp_ms": int(time.time() * 1000),
                    },
                    sort_keys=True,
                )
                + "\n"
            )


@dataclass(frozen=True)
class AdapterRegistry:
    profile: DeploymentProfile
    object_storage: ObjectStoragePort
    queue: QueuePort
    eventing: EventingPort
    secrets: SecretsPort
    log_sink: LogSinkPort

    def validate(self) -> "AdapterRegistry":
        for field_name, required_methods in PARITY_RULES.items():
            adapter = getattr(self, field_name)
            adapter_profile = getattr(adapter, "profile", None)

            if adapter_profile != self.profile:
                raise TypeError(
                    f"Adapter {field_name!r} advertises profile {adapter_profile!r}, expected {self.profile.value!r}."
                )

            missing_methods = [method_name for method_name in required_methods if not callable(getattr(adapter, method_name, None))]
            if missing_methods:
                raise TypeError(f"Adapter {field_name!r} is missing required methods: {', '.join(missing_methods)}")

        return self


def _build_registry(settings: AdapterSettings) -> AdapterRegistry:
    if settings.profile is DeploymentProfile.AWS:
        registry = AdapterRegistry(
            profile=settings.profile,
            object_storage=AwsObjectStorageAdapter(settings),
            queue=AwsQueueAdapter(settings),
            eventing=AwsEventingAdapter(settings),
            secrets=AwsSecretsAdapter(settings),
            log_sink=AwsLogSinkAdapter(settings),
        )
    else:
        registry = AdapterRegistry(
            profile=settings.profile,
            object_storage=OnPremObjectStorageAdapter(settings),
            queue=OnPremQueueAdapter(settings),
            eventing=OnPremEventingAdapter(settings),
            secrets=OnPremSecretsAdapter(settings),
            log_sink=OnPremLogSinkAdapter(settings),
        )

    return registry.validate()


def get_adapter_registry(env: Mapping[str, str] | None = None) -> AdapterRegistry:
    return _build_registry(AdapterSettings.from_env(env))


