from __future__ import annotations

import importlib
import time
import uuid
from pathlib import Path

import boto3
import pytest
from botocore.config import Config
from testcontainers.core.container import DockerContainer

import shared.adapters as adapters


def _configure_common_env(monkeypatch: pytest.MonkeyPatch, runtime_root: Path) -> None:
    monkeypatch.setenv("AWS_REGION", "us-east-1")
    monkeypatch.setenv("AWS_ACCESS_KEY_ID", "test")
    monkeypatch.setenv("AWS_SECRET_ACCESS_KEY", "test")
    monkeypatch.setenv("OBJECT_STORAGE_BUCKET", f"req001-{uuid.uuid4().hex[:8]}")
    monkeypatch.setenv("ONPREM_QUEUE_DIR", str(runtime_root / "queues"))
    monkeypatch.setenv("ONPREM_EVENT_LOG_PATH", str(runtime_root / "events.jsonl"))
    monkeypatch.setenv("ONPREM_LOG_PATH", str(runtime_root / "app.log.jsonl"))
    monkeypatch.setenv("ONPREM_SECRETS_DIR", str(runtime_root / "secrets"))
    monkeypatch.setenv("SECRET_TEST_SECRET", "local-dev-secret")


def _wait_for_s3(endpoint_url: str, *, access_key: str, secret_key: str, timeout_seconds: int = 90) -> None:
    client = boto3.client(
        "s3",
        endpoint_url=endpoint_url,
        aws_access_key_id=access_key,
        aws_secret_access_key=secret_key,
        region_name="us-east-1",
        config=Config(signature_version="s3v4", s3={"addressing_style": "path"}),
    )

    deadline = time.time() + timeout_seconds
    last_error: Exception | None = None

    while time.time() < deadline:
        try:
            client.list_buckets()
            return
        except Exception as exc:  # pragma: no cover - exercised only while container starts
            last_error = exc
            time.sleep(1)

    raise AssertionError(f"S3-compatible endpoint {endpoint_url} was not reachable in time: {last_error!r}")


def _business_round_trip(storage_port: adapters.ObjectStoragePort, key: str, payload: bytes) -> bytes:
    stored_key = storage_port.put_object(key, payload, content_type="application/octet-stream")
    assert stored_key == key
    return storage_port.get_object(key)


