    registry = adapters.get_adapter_registry().validate()

    assert registry.profile.value == profile
    assert type(registry.object_storage).__name__ == expected_class_names["object_storage"]
    assert type(registry.queue).__name__ == expected_class_names["queue"]
    assert type(registry.eventing).__name__ == expected_class_names["eventing"]
