def test_profile_switch_changes_adapter_bindings_without_code_changes(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _configure_common_env(monkeypatch, tmp_path)

    monkeypatch.setenv("DEPLOYMENT_PROFILE", "onprem")
    onprem_registry = adapters.get_adapter_registry().validate()

    monkeypatch.setenv("DEPLOYMENT_PROFILE", "aws")
    aws_registry = adapters.get_adapter_registry().validate()

    assert onprem_registry.profile is adapters.DeploymentProfile.ONPREM
    assert aws_registry.profile is adapters.DeploymentProfile.AWS
    assert type(onprem_registry.object_storage) is not type(aws_registry.object_storage)
    assert type(onprem_registry.queue) is not type(aws_registry.queue)
    assert type(onprem_registry.eventing) is not type(aws_registry.eventing)
    assert type(onprem_registry.secrets) is not type(aws_registry.secrets)
    assert type(onprem_registry.log_sink) is not type(aws_registry.log_sink)


def test_onprem_profile_stores_and_retrieves_object_with_minio(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    _configure_common_env(monkeypatch, tmp_path)
    monkeypatch.setenv("DEPLOYMENT_PROFILE", "onprem")

    with (
        DockerContainer("minio/minio:RELEASE.2024-01-16T16-07-38Z")
        .with_env("MINIO_ROOT_USER", "minioadmin")
        .with_env("MINIO_ROOT_PASSWORD", "minioadmin")
        .with_exposed_ports(9000)
        .with_command("server /data --console-address :9001") as container
    ):
        endpoint_url = f"http://{container.get_container_host_ip()}:{container.get_exposed_port(9000)}"
